def _obfuscate_command(self, command_args: Sequence[CommandArg], obfuscate_args: Optional[Iterable[CommandArg]]=None) -> ObfuscatedCommand:
    obfuscate_args = set(chain(obfuscate_args or [], self.default_obfuscation))
    obfuscated = ' '.join((self.obfuscation if any((re.match(arg, str(command_arg)) for arg in obfuscate_args)) else shlex.quote(str(command_arg)) for command_arg in command_args))
    return ObfuscatedCommand(obfuscated)

def process_msg(self, msg):
    cmd_id = rlp.decode(msg[:1], sedes=sedes.big_endian_int)
    self.logger.debug('Processing msg with cmd_id: {}'.format(cmd_id))
    proto = self.get_protocol_for(cmd_id)
    if proto is None:
        self.logger.warn('No protocol found for cmd_id {}'.format(cmd_id))
        return
    decoded_msg = proto.process(cmd_id, msg)
    if cmd_id == Hello.id:
        self.sub_protocols = {cap: proto for cap in self.capabilities if cap in decoded_msg['capabilities']}
        self.logger.debug('Got hello: {}'.format(decoded_msg))

def fetch_historical_prices_by_epic_and_date_range(self, epic, resolution, start_date, end_date, session=None, format=None):
    if self.return_dataframe:
        resolution = conv_resol(resolution)
    version = '2'
    start_date = conv_datetime(start_date, version)
    end_date = conv_datetime(end_date, version)
    params = {'startdate': start_date, 'enddate': end_date}
    url_params = {'epic': epic, 'resolution': resolution}
    endpoint = '/prices/{epic}/{resolution}'.format(**url_params)
    action = 'read'
    response = self._req(action, endpoint, params, session, version)
    del self.crud_session.HEADERS['LOGGED_IN']['VERSION']
    data = self.parse_response(response.text)
    if format is None:
        format = self.format_prices
    if self.return_dataframe:
        data['prices'] = format(data['prices'], version)
        data['prices'] = data['prices'].fillna(value=np.nan)
    return data

