def _parse_expression(self, inTemplate: bool) -> ASTExpression:
    left_expr = self._parse_assignment_expression(inTemplate=inTemplate)
    if self._match(','):
        self._consume(',')
        right_expr = self._parse_assignment_expression(inTemplate=inTemplate)
        return ASTExpression(left_expr, right_expr)
    return left_expr

def query_by_short_id(context, model, short_id, project_safe=True):
    q = model_query(context, model)
    q = q.filter(model.id.like('%s%%' % short_id))
    if project_safe:
        q = q.filter_by(project=context.project)
    if q.count() == 1:
        return q.first()
    elif q.count() == 0:
        return None
    else:
        raise exception.MultipleChoices(arg=short_id)

