def _get_event_ids_for_partial_state_join(join_event: EventBase, prev_state_ids: StateMap[str]) -> Collection[str]:
    state_event_ids = {event_id for ((event_type, state_key), event_id) in prev_state_ids.items() if event_type != EventTypes.Member}
    current_membership_event_id = prev_state_ids.get((EventTypes.Member, join_event.state_key))
    if current_membership_event_id is not None:
        state_event_ids.add(current_membership_event_id)
    state_event_ids.update((event_id for ((event_type, state_key), event_id) in prev_state_ids.items() if event_type == EventTypes.Member and (state_key == 'invite' or state_key == 'kicked' or state_key == 'banned')))
    return state_event_ids

def _build_dict(self):
    data = {}
    data['message_type'] = NotificationType.type_names[self._type]
    data['message_data'] = {}
    data['message_data']['event_key'] = self.event.key_name
    data['message_data']['event_name'] = self.event.name
    data['message_data']['match_key'] = self.match.key_name
    data['message_data']['team_keys'] = self.match.team_key_names
    if self.match.time:
        data['message_data']['scheduled_time'] = calendar.timegm(self.match.time.utctimetuple())
        data['message_data']['predicted_time'] = self._calculate_predicted_time(self.match.time)
    else:
        data['message_data']['scheduled_time'] = None
        data['message_data']['predicted_time'] = None
    current_webcasts = self.event.current_webcasts
    WebcastOnlineHelper.add_online_status(current_webcasts)
    online_webcasts = filter(lambda x: x.get('status', '') != 'offline', current_webcasts if current_webcasts else [])
    if online_webcasts:
        data['message_data']['webcast'] = online_webcasts[0]
    else:
        data['message_data']['webcast'] = None
    return data

