def check_htmllinks(path):
    ddir = docdir.localpath
    for (lineno, line) in py.builtin.enumerate(path.readlines()):
        line = line.strip()
        if line.startswith('.. _'):
            l = line.split(':', 1)
            if len(l) != 2:
                continue
            tryfn = l[1].strip()
            if tryfn.startswith('http:'):
                import urllib.request
                response = urllib.request.urlopen(tryfn)
                if response.getcode() != 200:
                    py.test.fail('URL %r returned error %d' % (tryfn, response.getcode()))
            elif tryfn.endswith('.html'):
                fn = ddir.join(tryfn)
                fn = fn.new(ext='.txt')
                if not fn.check(file=1):
                    py.test.fail('reference error %r in %s:%d' % (tryfn, path.basename, lineno + 1))
            else:
                pass

def _retrieve(self, url):
    encode = 'latin1'
    try:
        uopener = self.urlOpener.open(url)
        content = uopener.read()
        info_dict = uopener.info()
        if info_dict.has_key('Content-Type'):
            ct_line = info_dict['Content-Type'].lower()
            csi = ct_line.find('charset=')
            if csi != -1:
                encode = ct_line[csi+9:]
                if not isinstance(encode, str) or not encode:
                    encode = 'latin1'
        uopener.close()
        self.urlOpener.close()
    except IOError, e:
        raise IMDbDataAccessError, {'errcode': e.errno,
                                    'errmsg': str(e.strerror),
                                    'url': url,
                                    'proxy': self.get_proxy()}
    return unicode(content, encode, 'replace')

def config_init(prompt=True):
    config_path = os.getcwd() + '/.wandb'
    config = Config()
    if os.path.isdir(config_path):
        if prompt:
            click.confirm(click.style('This directory is already initialized, should we overwrite it?', fg='red'), abort=True)
    else:
        tmp_path = config_path.replace('.wandb', '.wandb.tmp')
        if os.path.isfile(config_path):
            os.rename(config_path, tmp_path)
        os.mkdir(config_path)
        if os.path.isfile(tmp_path):
            os.rename(tmp_path, tmp_path.replace('.wandb.tmp', '.wandb/config'))
    config.batch_size_desc = 'Number of training examples in a mini-batch'
    config.batch_size = 32
    config.persist()
    if prompt:
        click.echo('Configuration initialized, use `wandb config set` to set parameters.  Then in your training script:\n\nimport wandb\nconf = wandb.Config()\nconf.batch_size\n')

