def topics_for(products, parent=False):
    statsd.incr('wiki.facets.topics_for.db')
    docs = Document.objects.filter(locale=settings.WIKI_DEFAULT_LANGUAGE, is_archived=False, current_revision__isnull=False, category__in=settings.IA_DEFAULT_CATEGORIES)
    for product in products:
        docs = docs.filter(products=product)
    qs = Topic.objects
    qs = qs.filter(visible=True, document__in=docs).annotate(num_docs=Count('document')).distinct()
    if parent or parent is None:
        qs = qs.filter(parent=parent)
    return qs

def create_task(self, task_dict, force=False) -> typing.Tuple[typing.Optional[str], typing.Optional[str]]:
    task: taskbase.Task
    if isinstance(task_dict, taskbase.Task):
        warnings.warn('create_task() called with {got_type} instead of dict #2467'.format(got_type=type(task_dict)), DeprecationWarning, stacklevel=2)
        task = task_dict
    else:
        prepare_and_validate_task_dict(self.client, task_dict)
        task = self.task_manager.create_task(task_dict)
    task_id = task.header.task_id
    deferred = enqueue_new_task(self.client, task, force=force)
    deferred.addErrback(lambda failure: _create_task_error(e=failure.value, _self=self, task_dict=task_dict, force=force))
    return (task_id, None)

