def __init__(self, url):
    if isinstance(url, bytes):
        url = url.decode('utf8')
        if not url.startswith(('http://', 'https://')):
            raise ValueError('URL must start with http:// or https://')
    self.url = url

def publish_event_object(self, event_object):
    assert event_object
    topic = self._topic(event_object)
    to_name = (self._send_name.exchange, topic)
    log.trace('Publishing event message to %s', to_name)
    current_time = int(get_ion_ts())
    if event_object.ts_created:
        if not is_valid_ts(event_object.ts_created):
            raise BadRequest("The ts_created value is not a valid timestamp: '%s'" % event_object.ts_created)
        if int(event_object.ts_created) > current_time + VALID_EVENT_TIME_PERIOD:
            raise BadRequest("This ts_created value is too far in the future:'%s'" % event_object.ts_created)
        if int(event_object.ts_created) < current_time - VALID_EVENT_TIME_PERIOD:
            raise BadRequest("This ts_created value is too old:'%s'" % event_object.ts_created)
    else:
        event_object.ts_created = str(current_time)
    event_object._validate()
    if '_id' in event_object:
        raise BadRequest("The event object cannot contain a _id field '%s'" % event_object)
    event_object._id = create_unique_event_id()
    try:
        self.publish(event_object, to_name=to_name)
    except Exception as ex:
        log.exception("Failed to publish event (%s): '%s'" % (ex.message, event_object))
        raise
    return event_object

def main():
    configure_logging()
    arguments = parse_options()
    (controller_class, controller_kwargs) = select_device(arguments)
    controller = controller_class(**controller_kwargs)
    if arguments.command == 'version':
        version(controller)
    elif arguments.command == 'reset':
        reset(controller)
    elif arguments.command.startswith('write'):
        if arguments.command == 'write':
            if arguments.write_name:
                controller.write(name=arguments.write_name, value=arguments.write_value, event=arguments.write_event)
            elif arguments.write_id:
                if not arguments.write_data:
                    sys.exit('%s requires an id and data' % arguments.command)
                controller.write(id=arguments.write_id, data=arguments.write_data, bus=arguments.write_bus)
            elif arguments.write_input_file:
                write_file(controller, arguments.write_input_file)
            else:
                sys.exit('%s requires a signal name, message ID or filename' % arguments.command)
    else:
        print('Unrecognized command "%s"' % arguments.command)

def upload_handler(request, site_short_name):
    view_url = reverse('comicmodels.views.upload_handler', kwargs={'site_short_name': site_short_name})
    if request.method == 'POST':
        site = getSite(site_short_name)
        uploadedFile = UploadModel(comicsite=site, permission_lvl=UploadModel.ADMIN_ONLY, user=request.user)
        form = UserUploadForm(request.POST, request.FILES, instance=uploadedFile)
        if form.is_valid():
            form.save()
            filename = ntpath.basename(form.instance.file.file.name)
            messages.success(request, "File '%s' sucessfully uploaded. An email has been sent to this                                       projects organizers." % filename)
            send_email_notification(site, request.user, filename)
            return HttpResponseRedirect(view_url)
        else:
            pass
    else:
        form = UserUploadForm()
    (upload_url, upload_data) = prepare_upload(request, view_url)
    [site, pages, metafooterpages] = site_get_standard_vars(site_short_name)
    if not (site.is_admin(request.user) or site.is_participant(request.user)):
        p = Page(comicsite=site, title='files')
        currentpage = permissionMessage(request, site, p)
        return render_to_response('page.html', {'site': site, 'currentpage': currentpage, 'pages': pages, 'metafooterpages': metafooterpages}, context_instance=RequestContext(request))
    if request.user.is_superuser or site.is_admin(request.user):
        uploadsforcurrentsite = UploadModel.objects.filter(comicsite=site).order_by('modified').reverse()
    else:
        uploadsforcurrentsite = UploadModel.objects.filter(user=request.user).order_by('modified').reverse()
    return render(request, 'upload/comicupload.html', {'form': form, 'upload_url': upload_url, 'upload_data': upload_data, 'uploads': uploadsforcurrentsite, 'site': site, 'pages': pages, 'metafooterpages': metafooterpages})

