def tobsr(self, blocksize=None, copy=True):
    if blocksize == (1, 1):
        from bsr import bsr_matrix
        arg1 = (self.data.reshape(-1, 1, 1), self.indices, self.indptr)
        return bsr_matrix(arg1, shape=self.shape, copy=copy)
    else:
        return bsr_matrix((self.data.reshape(-1, blocksize[0], blocksize[1]), self.indices, self.indptr), shape=self.shape, copy=copy) if blocksize else self.tocoo(copy=False).tobsr(blocksize=blocksize)

def new_path(road_map: MapInterface, trace: Trace, distance_epsilon: float) -> List[Road]:
    if len(trace.coords) < 1:
        return []
    origin = trace.coords[0]
    destination = trace.coords[-1]
    time_path = road_map.shortest_path(origin, destination, weight=road_map.get_time_weight())
    dist_path = road_map.shortest_path(origin, destination, weight=road_map.get_distance_weight())
    time_score = score(trace, time_path, distance_epsilon)
    dist_score = score(trace, dist_path, distance_epsilon)
    if dist_score > time_score:
        return dist_path
    else:
        return time_path

