def parse_42_guid(guid):
    guid_parts = guid.split('-')
    return struct.unpack('>IIQ', bytes.fromhex(''.join(guid_parts)[:32]))

def compute_output_spec(self, x, key):
    if not isinstance(key, (int, slice)):
        raise ValueError(f'Only scalar int keys are supported at this time. Cannot process key {key}')
    if len(x.shape) == 0:
        raise ValueError(f'Too many indices for array: array is scalar but index {key} was requested. A scalar array cannot be indexed.')
    if x.shape[0] is not None and isinstance(key, int) and (key >= x.shape[0]):
        raise ValueError(f'Array has shape {x.shape} but out-of-bound index {key} was requested.')
    return KerasTensor(x.shape[1:], dtype=x.dtype)

