def compute(self, name, grid=None, data=None, M_booz=None, N_booz=None):
    if name not in data_index:
        raise ValueError("Unrecognized value '{}'.".format(name))
    if grid is None:
        grid = QuadratureGrid(self.L, self.M, self.N, self.NFP)
    fun = getattr(compute_funs, data_index[name]['fun'])
    sig = signature(fun)
    inputs = {'data': data}
    for arg in sig.parameters.keys():
        if arg in arg_order:
            inputs[arg] = getattr(self, arg)
        elif arg == 'R_transform':
            inputs[arg] = Transform(grid, self.R_basis, derivs=data_index[name]['R_derivs'])
        elif arg == 'Z_transform':
            inputs[arg] = Transform(grid, self.Z_basis, derivs=data_index[name]['R_derivs'])
        elif arg == 'L_transform':
            inputs[arg] = Transform(grid, self.L_basis, derivs=data_index[name]['L_derivs'])
        elif arg == 'B_transform':
            inputs[arg] = Transform(grid, DoubleFourierSeries(M=2 * self.M, N=2 * self.N, sym=self.R_basis.sym, NFP=self.NFP), derivs=0, build_pinv=True)
        elif arg == 'w_transform':
            inputs[arg] = Transform(grid, DoubleFourierSeries(M=2 * self.M, N=2 * self.N, sym=self.Z_basis.sym, NFP=self.NFP), derivs=1)
        elif arg == 'pressure':
            inputs[arg] = self.pressure.copy()
            inputs[arg].grid = grid
        elif arg == 'iota':
            inputs[arg] = self.iota.copy()
            inputs[arg].grid = grid
    return fun(**inputs)

